import {ADVANCED,UNLOCK_COST,growth,isAdvanced,installAdvanced} from './expedition-growth.mjs';
import {rewardPreview,gearDifference,isRelic} from './expedition-loot.mjs';
import {redeemHarbor,GUILD_KEY,GEAR_PRICE,historyConfig,historyReport,newGuild,validateGuild,migrateGuild,pendingReward,assignLoot,sellLoot,guildConfig,depart,pendingReport,rewardFor,claim,train,lowerTraining,chooseAdvancement,resetAdvancement,equip,retrain,learnAdvanced} from './expedition-guild.mjs';
import {HEROES,GEAR,ATTR,SKILLS,POS,DEFENSES,ITEMS,roomsFor,EXPEDITIONS,trainingOptions,trainingCost,MAX_TRAINING_RANK} from './expedition-data.mjs';
export function mountGuild({getConfig,loadConfig,showReport,view,tell,download,editHero,updateConfig}){
 const root=document.querySelector('#guild'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let raw=null,g=null,selected='a',failure='',checkScope='',pane='hero',message='',gearFilter='owned',equipmentSlot='all',compareId=null,compareMode='draft',companionRoom='',previews={};
 const paneNames={roster:'招募与出战',hero:'我的英雄与伙伴',departure:'出征准备',team:'角色成长',equipment:'装备与仓库',contracts:'港口委托',history:'履历与备份'};
 try{const ui=JSON.parse(sessionStorage.getItem('abbey-guild-ui')||'null');if(ui){if(Object.hasOwn(paneNames,ui.pane))pane=ui.pane;if(HEROES.some(h=>h.id===ui.selected))selected=ui.selected;if(typeof ui.checkScope==='string')checkScope=ui.checkScope;if(['owned','shop','all'].includes(ui.gearFilter))gearFilter=ui.gearFilter;}}catch{}
 function remember(){try{sessionStorage.setItem('abbey-guild-ui',JSON.stringify({pane,selected,checkScope,gearFilter}));}catch{}}
 function inform(text){message=text;tell(text);const box=root.querySelector("#guild-feedback");if(box)box.textContent=text;}
 function panels(){for(const el of root.querySelectorAll('[data-guild-pane]'))el.hidden=el.dataset.guildPane!==pane;for(const b of root.querySelectorAll('[data-guild-tab]')){const active=b.dataset.guildTab===pane;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}remember();}
 function switchPanel(next){pane=next;render();root.querySelector(`[data-guild-tab="${pane}"]`)?.focus();root.querySelector('.guild-tabs')?.scrollIntoView({block:'start'});}
 function read(){try{raw=localStorage.getItem(GUILD_KEY);g=migrateGuild(raw?JSON.parse(raw):newGuild());failure='';if(!raw)message='港口远征版使用独立公会存档；此前版本存档不迁移。请先选择自己的英雄。';}catch(e){g=null;failure=e.message;}}
 function save(next){validateGuild(next);if(localStorage.getItem(GUILD_KEY)!==raw)throw Error('另一页面已修改公会，请重新进入公会后再操作');const text=JSON.stringify(next);localStorage.setItem(GUILD_KEY,text);raw=text;g=next;}
 function comparisonHTML(){
 if(!compareId||!g.history.some(r=>r.id===compareId&&r.config))return '';
 const d=historyComparison(g,compareId,getConfig(),compareMode);
 const rows=items=>items.length?`<div class="history-diff-scroll"><table class="history-diff-table"><thead><tr><th>配置项</th><th>历史出征</th><th>${compareMode==='guild'?'当前公会资产＋当前战术':'当前准备方案'}</th></tr></thead><tbody>${items.map(c=>`<tr><th scope="row">${esc(c.label)}</th><td>${esc(c.before)}</td><td>${esc(c.after)}</td></tr>`).join('')}</tbody></table></div>`:'<p>无差异。</p>';
 return `<section id="history-comparison" class="guild-panel" data-guild-pane="history"><h2>第${compareId}次远征 → 当前方案</h2><label>比较对象 <select id="history-compare-mode"><option value="draft" ${compareMode==='draft'?'selected':''}>当前准备方案</option><option value="guild" ${compareMode==='guild'?'selected':''}>当前公会资产＋当前战术</option></select></label><p>${d.total} 项配置差异。左侧为历史，右侧为当前；仅列出变化，不判断改动是否更好。</p><p>公会模式采用伙伴职责及现有装备与训练；种子仍显示准备页值，实际出征会分配新种子。技能学习与出征资格请到出征准备核对。</p>${d.routeChanged?'<p class="ready-diff">两份方案路线不同；房间按配置槽比较，不代表相同敌人或战斗环境。</p>':''}<h3>全队与路线</h3>${rows(d.global)}${d.heroes.map(h=>`<details ${h.changes.length?'open':''}><summary>${h.name} · ${h.changes.length} 项变化</summary>${rows(h.changes)}</details>`).join('')}<button data-history-load="${compareId}">载入这次历史方案</button><button data-history-close="true">关闭对比</button></section>`;
 }
 function render(){
 if(!g){root.innerHTML=`<h1>公会存档暂不可用</h1><p>${esc(failure)}。原存档未覆盖。</p><button data-guild="backup">导出原始存档</button><label>恢复有效备份 <input type="file" id="guild-import" accept="application/json,.json"></label>`;return;}
 if(!g.members.some(m=>m.id===selected))selected=g.lineup[0];
 if(checkScope&&!roomsFor(getConfig()).some(r=>r.id===checkScope))checkScope='';
 if(companionRoom&&!roomsFor(getConfig()).some(r=>r.id===companionRoom))companionRoom='';
 const ready=readiness(g,getConfig(),checkScope);
 const advancement=advancementStatus(g,selected);
 const m=g.members.find(h=>h.id===selected),hero=HEROES.find(h=>h.id===selected),pending=g.pending?pendingReward(g):null,progress=growth(m),advanced=ADVANCED[m.id],learned=m.unlocked.includes(advanced);
 root.innerHTML=`<div class="guild-hub"><p class="eyebrow">海岸公会 / 常驻营地</p><div class="guild-hub-row"><div><h1>整备，再次出发。</h1><p>${esc(EXPEDITIONS[getConfig().expedition].name)} · 金币 <strong>${g.gold}</strong> · 已完成 ${g.next-1-(g.pending?1:0)} 次远征</p></div><button data-guild="prepare">到准备页调整战术 →</button></div><p id="guild-feedback" role="status">${esc(message||'选择一个面板管理队伍。出征使用公会实际装备与训练。')}</p></div><nav class="guild-tabs" aria-label="公会面板">${Object.entries(paneNames).map(([key,label])=>`<button data-guild-tab="${key}">${label}${key==='equipment'?' · '+Object.values(g.warehouse).reduce((a,b)=>a+b,0):''}</button>`).join('')}</nav>
 ${commandHome(g,rosterConfig(g,getConfig()),previews,companionRoom)}${rosterHome(g)}
 ${harborContracts(g)}
 ${pending?`<section class="guild-panel"><h2>第 ${g.pending.id} 次远征待结算</h2><p>通过 ${pending.cleared} 场 · ${pending.gold} 金币 · 每位出战者 ${pending.xp} 经验。刷新页面仍可恢复。</p><p>${pending.firstClear?'首次通关加成已计入。':''}${pending.loot?.length?'装备：'+pending.loot.map(k=>GEAR[k].name).join('、'):'本次无装备掉落。'}</p>${pending.harbor?`<p>海图 +${pending.harbor.charts}；新达成委托：${pending.harbor.earned.map(id=>HARBOR_OBJECTIVES[id].name).join("、")||"无"}（委托金币已计入上方总额）。</p>`:""}<button data-guild="report">查看本次战报</button><button class="primary" data-guild="claim">领取奖励并归营</button></section>`:''}
 <section class="guild-panel departure-check" data-guild-pane="departure" id="departure-check"><p class="eyebrow">出发前 / 公会实际配置</p><h2>${esc(EXPEDITIONS[getConfig().expedition].name)} · 六人出征核对</h2><label>查看指令与站位 <select id="check-scope"><option value="">默认与全路线提醒</option>${roomsFor(getConfig()).map(r=>`<option value="${r.id}" ${checkScope===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><p>下方装备与训练就是本次公会出征所用值。战术来自准备页，房间覆盖可切换查看。检查不预测胜负或资源能否撑到末场。</p>${ready.config.expedition==='harbor'?`<p class="ready-harbor">港口计划：${HARBOR_DIFFICULTY[harborDifficulty(ready.config)]} / ${HARBOR_PASS[ready.config.harbor.pass]} / ${HARBOR_TASK[ready.config.harbor.task]} / ${HARBOR_RESERVE[harborReserve(ready.config)]}。抵达时按实际存活者与剩余物资结算；整段远征不暂停改配。</p>`:''}${cooperationView(ready.cooperation,{actual:true})}<div class="ready-grid">${ready.heroes.map(h=>`<article class="ready-hero"><p class="eyebrow">${h.role} · ${POS[h.plan.pos]}</p><h3>${h.name} · ${commandLabel(g,h.id)}</h3><p>${h.gearName} · 生命${h.hp} / 法力${h.mp}</p><p>永久训练 · 累计投入 ${trainingInvestment(h.training)}经验：${Object.entries(h.training).filter(([,n])=>n>0).map(([k,n])=>`${esc(trainingOptions(h.id)[k].name)}+${n}`).join('、')||'未分配'}</p>${h.gearChanged||h.trainingChanged?`<p class="ready-diff">准备页${h.gearChanged?`装备为${h.draftGearName}`:''}${h.gearChanged&&h.trainingChanged?'，':''}${h.trainingChanged?'训练配置不同':''}；出征以本卡公会资产为准。</p>`:''}<p>后期进阶：${h.advancement?ADVANCEMENTS[h.advancement].name:'未选择'}</p><p>专修 ${SKILLS[h.trained].name} · ${DEFENSES[h.defenseFocus].name} / ${ATTR[h.attribute]}</p><p>防御 ${Object.values(h.plan.defenses).map(k=>DEFENSES[k].name).join(' / ')}</p><p>道具 ${ITEMS[h.item].name} · ${h.plan.itemPolicy.enabled?'自动使用':'停用'}${h.plan.healing.enabled?`<br>救护 ≤${Math.round(h.plan.healing.threshold*100)}% · ${h.plan.healing.priority==='self_first'?'优先自保':'最低生命比例'} · ${POS[h.plan.healing.target]||{all:'全队',self:'自身'}[h.plan.healing.target]}`:''}</p><p><b>预备</b> ${h.plan.prep.map(r=>`${SKILLS[r.skill].name} → ${POS[r.target]||{self:'自身',all:'全队',healer:'治疗者',summoner:'召唤者'}[r.target]}（${{round:'每回合一次',repeat:'持续',once:'一次',cycle:'轮转'}[r.mode]}）`).join('；')||'无'}</p><p><b>普通</b> ${h.plan.main.map(r=>`${SKILLS[r.skill].name} → ${POS[r.target]||{self:'自身',all:'全队',healer:'治疗者',summoner:'召唤者'}[r.target]}（${{round:'每回合一次',repeat:'持续',once:'一次',cycle:'轮转'}[r.mode]}）`).join('；')||'无'}</p>${h.warnings.length?`<ul class="ready-warnings">${h.warnings.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}<button data-ready-edit="${h.id}">调整此人战术</button><button data-ready-member="${h.id}">装备与成长</button></article>`).join('')}</div>${ready.errors.length?`<div class="ready-errors">${ready.errors.map(e=>`<p>${HEROES.find(h=>h.id===e.id).name}：${esc(e.text)}</p>`).join('')}</div>`:''}<p>${ready.pending?'上次远征尚未结算，请先领取奖励。':ready.errors.length?'请处理未学习技能后再出征。':'可出征。装备与资源提醒不会自动改动指令。'}</p><button data-guild="depart" class="primary" ${ready.canDepart?'':'disabled'}>以以上公会配置出征 →</button></section>
 ${['seasoned','veteran'].includes(getConfig().expedition)?`<section class="guild-panel" data-guild-pane="departure"><h2>阶段建议</h2><p>本路线建议${getConfig().expedition==='seasoned'?'熟练':'资深'}阶段。当前队伍最低阶段 ${Math.min(...g.members.map(h=>growth(h).level))} / 3。阶段只开放技能学习与训练，不直接增加属性，也不限制出征。</p><p>请在准备页查看敌方位置、抗性和职责；可对比正面突破、统一集火、分工保护三套方案。</p></section>`:''}
 <section class="guild-panel" data-guild-pane="departure"><h2>本次路线奖励 · ${esc(EXPEDITIONS[getConfig().expedition].name)}</h2><p>${rewardPreview(getConfig().expedition)}</p><p>${g.clears[getConfig().expedition]?`已通关 ${g.clears[getConfig().expedition]} 次`:'本版首次通关奖励尚未领取'}。装备分配到个人后永久持有；仓库重复装备可出售。</p></section>

 <section class="guild-panel" data-guild-pane="team"><h2>常驻队员</h2><div class="bar">${HEROES.filter(h=>g.members.some(m=>m.id===h.id)).map(h=>`<button data-member="${h.id}" class="${h.id===selected?'active':''}">${h.name}</button>`).join('')}</div><h3>${hero.name} · ${hero.role}</h3><p>可用经验 ${m.xp} · 永久训练投入 ${trainingInvestment(m.training)}经验 · 当前装备 ${equipmentName(m.gear)}</p>${experienceView(m)}<section class="growth-card"><p class="eyebrow">职业课程 · ${PROGRESSION_RULES.stages.find(s=>s.level===progress.level).name} / 阶段 ${progress.level}</p><h3>${SKILLS[advanced].name}</h3><p>${SKILLS[advanced].desc}</p><p>累计经验 ${progress.earned}${progress.next?` / 下一阶段 ${progress.next}`:' · 已达到当前阶段上限'}。累计值包含已用于训练、课程与后期进阶的经验，重修不改变成长阶段。</p><p>${COURSE_REQUIRED_XP}累计经验：可花${UNLOCK_COST}经验学习本职业高阶普通技能；${PROGRESSION_RULES.stages.at(-1).earned}累计经验：高阶普通技能训练上限从${PROGRESSION_RULES.stages[1].advancedRank}级提升至${MAX_TRAINING_RANK}级。各技能自由培养，按逐级经验成本投入。</p><button data-unlock="${m.id}" ${g.pending||learned||progress.level<PROGRESSION_RULES.course.requiredStage||m.xp<UNLOCK_COST?'disabled':''}>${learned?'已永久学习':'学习 · '+UNLOCK_COST+'经验'}</button><button data-install="${advanced}" ${!learned?'disabled':''}>加入当前${SKILLS[advanced].kind==='buff'?'预备':'普通'}指令</button><small>加入时置于首条，清除该角色同阶段房间覆盖；其余指令保留，满4条时请先腾出位置。</small></section><details class=advancement-card><summary>独立后期职业进阶 · ${advancement.selected?ADVANCEMENTS[advancement.selected].name:'未选择'}</summary><p>本项目门槛：累计${ADVANCEMENT_REQUIRED_XP}经验、公会通关资深试炼，选择消耗${ADVANCEMENT_COST}经验。普通技能、已学课程与训练保留，不互斥；当前重选先退回原进阶，精确返还${ADVANCEMENT_COST}经验。</p>${advancement.options.length?`${advancement.reasons.length?`<p class=ready-diff>${esc(advancement.reasons.join('；'))}</p>`:''}<div class=advancement-options>${advancement.options.map(([key,a])=>`<article><h4>${a.name}</h4><p>${a.desc}</p><button data-advancement="${key}" ${!advancement.allowed?'disabled':''}>选择 · ${ADVANCEMENT_COST}经验</button></article>`).join('')}</div><button data-reset-advancement="${m.id}" ${g.pending||!m.advancement?'disabled':''}>退回进阶 · ${ADVANCEMENT_COST}经验</button>`:'<p>该职业的后期进阶尚未开放，普通技能仍可自由培养。</p>'}</details><p>本职业普通技能可自由搭配培养。每项训练最高${MAX_TRAINING_RANK}级，逐级花费${trainingCostText}经验，可单独退回一级并返还该级实际投入；整项累计${trainingTotalText}经验。固定效果不因技能等级自动增强。</p><div class="training-grid">${Object.entries(trainingOptions(m.id)).filter(([,o])=>!isAdvanced(o.id)||m.unlocked.includes(o.id)).map(([key,o])=>{const q=trainingQuote(m,key),down=trainingQuote(m,key,-1);return `<article class="training-row"><div><b>${o.name}</b><p>永久训练 +${q.rank} · 已投入 ${q.invested}经验</p>${q.allowed?'':`<small>${esc(q.reasons.join('；'))}</small>`}</div><div><button data-learn="${key}" ${g.pending||!q.allowed?'disabled':''}>${q.rank===MAX_TRAINING_RANK?'已满级':`训练 · ${q.cost}经验`}</button><button data-untrain="${key}" ${g.pending||!down.allowed?'disabled':''}>退回一级 · ${down.refund}经验</button></div></article>`;}).join('')}</div><button data-guild="retrain" ${g.pending||!trainingCost(m.training)?'disabled':''}>重修训练（全额返还经验）</button><button data-guild-tab="equipment">查看此人装备 →</button></section>${equipmentPanel(g,selected,gearFilter,equipmentSlot,ready.config?.heroes.find(h=>h.id===selected)||getConfig().heroes.find(h=>h.id===selected)||m.tactics)}
 <section class="guild-panel" data-guild-pane="history"><h2>远征履历</h2><p>保留最近20次结算与出征方案。按当前规则重演，不发放奖励；规则更新后重演结果可能与历史结算不同。</p>${g.history.length?g.history.map(r=>`<p>第${r.id}次 · ${esc(EXPEDITIONS[r.route]?.name||r.route)} · ${r.won?'通关':'止步'} · ${r.cleared}场 · ${r.gold}金币 / 每位出战者${r.xp}经验 ${r.firstClear?'· 首通':''} ${(r.loot||[]).map(k=>esc(GEAR[k]?.name||k)).join('、')}</p>${r.config?`<div class="bar"><button data-history-compare="${r.id}">对比当前方案</button><button data-history-report="${r.id}">重演第${r.id}次远征</button><button data-history-load="${r.id}">载入第${r.id}次方案</button><small>种子 ${r.config.seed} · 当时装备与训练快照</small></div>`:'<small>此记录没有保存出征方案</small>'}`).join(''):'<p>还没有已结算远征。建议从回声侧廊或基础修道院开始。</p>'}<h3>本机存档</h3><p>公会保存在当前浏览器，暂不跨设备同步。导入备份会替换当前公会；实验战斗不发奖励。</p><button data-guild="backup">导出公会备份</button><label class="guild-import">恢复备份 <input type="file" id="guild-import" accept="application/json,.json"></label></section>${comparisonHTML()}`;
 panels();
 }
 root.onclick=e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.recruit){save(recruit(g,b.dataset.recruit));inform('新伙伴已加入候补名册，尚未替换出战队员。');render();return;}
 else if(b.dataset.swap){const out=root.querySelector('#replace-'+b.dataset.swap).value;save(swapCompanion(g,getConfig(),out,b.dataset.swap));updateConfig(rosterConfig(g,getConfig()));previews={};inform('出战伙伴已替换；原伙伴的装备、经验和战术仍保留。');render();return;}
 else if(b.dataset.applyCompanion){const id=b.dataset.applyCompanion;save(setCompanion(g,id,previews[id]));delete previews[id];inform('伙伴职责已应用；出征核对将使用此职责。');render();return;}
 else if(b.dataset.cancelCompanion){delete previews[b.dataset.cancelCompanion];render();return;}
 else if(b.dataset.ownHero){previews={};save(selectHero(g,b.dataset.ownHero));selected=b.dataset.ownHero;inform('已选择自己的英雄；伙伴职责可在下方设置。');render();return;}
 else if(b.dataset.personal){selected=g.command.heroId;if(b.dataset.personal==='tactics'){updateConfig(rosterConfig(g,getConfig()));editHero(selected,'');return;}switchPanel(b.dataset.personal==='growth'?'team':'equipment');return;}
 else if(b.dataset.historyCompare){compareId=Number(b.dataset.historyCompare);render();root.querySelector('#history-comparison')?.scrollIntoView({block:'start'});return;}
 else if(b.dataset.historyClose){compareId=null;render();root.querySelector('.guild-tabs')?.scrollIntoView({block:'start'});return;}
 else if(b.dataset.historyReport){showReport(historyReport(g,Number(b.dataset.historyReport)));inform('正在按当前规则重演第'+b.dataset.historyReport+'次远征，不发放奖励。');return;}
 else if(b.dataset.historyLoad){loadConfig(historyConfig(g,Number(b.dataset.historyLoad)));inform('历史出征方案已载入，可撤销。再次公会出征使用当前装备与训练，并采用新的出征种子。');return;}
 else if(b.dataset.guildTab){switchPanel(b.dataset.guildTab);return;}
 else if(b.dataset.member)selected=b.dataset.member;
 else if(b.dataset.cooperationEdit){const id=b.dataset.cooperationEdit,room=b.dataset.cooperationRoom,edit=customizeForEditing(g,getConfig(),id,room);delete previews[id];if(edit.changed)save(edit.guild);updateConfig(edit.config);editHero(id,room,b.dataset.cooperationRow);inform('已保留当前实际职责指令并切到自定义，可从本房继续修改。');return;}
 else if(b.dataset.readyEdit){const id=b.dataset.readyEdit,edit=customizeForEditing(g,getConfig(),id,checkScope);delete previews[id];if(edit.changed)save(edit.guild);updateConfig(edit.config);editHero(id,checkScope);inform('已保留当前实际职责指令；该队员现使用自定义，可逐房调整。');return;}
 else if(b.dataset.readyMember){selected=b.dataset.readyMember;switchPanel("team");return;}
 else if(b.dataset.advancement){save(chooseAdvancement(g,selected,b.dataset.advancement));inform('已选择后期职业进阶，普通技能和训练保留。');}
 else if(b.dataset.resetAdvancement){save(resetAdvancement(g,b.dataset.resetAdvancement));inform('已退回后期进阶并返还'+ADVANCEMENT_COST+'经验；普通技能和训练保留。');}
 else if(b.dataset.unlock)save(learnAdvanced(g,b.dataset.unlock));
 else if(b.dataset.install){const edit=customizeForEditing(g,getConfig(),selected),installed=installAdvanced(edit.config,selected,b.dataset.install);if(edit.changed)save(edit.guild);delete previews[selected];loadConfig(installed);inform("已保留实际职责并加入高阶普通技能；伙伴现为自定义，该阶段逐房指令覆盖已清除。请核对目标、资源与行动顺序；可撤销方案载入。");return;}
 else if(b.dataset.assign){save(assignLoot(g,selected,b.dataset.assign));inform("战利品已分配并装备，可在已持有装备中查看。");}
 else if(b.dataset.sell)save(sellLoot(g,b.dataset.sell));
 else if(b.dataset.learn)save(train(g,selected,b.dataset.learn));
 else if(b.dataset.untrain){const key=b.dataset.untrain,q=trainingQuote(g.members.find(m=>m.id===selected),key,-1);save(lowerTraining(g,selected,key));inform('已退回'+q.name+'一级，返还'+q.refund+'经验；其他训练和已学技能保留。');}
 else if(b.dataset.equipmentSlot){equipmentSlot=b.dataset.equipmentSlot;gearFilter='all';}
 else if(b.dataset.harborRedeem){save(redeemHarbor(g,b.dataset.harborRedeem));inform('海图已兑换，装备进入公会仓库，可在装备与仓库分配。');}
 else if(b.dataset.equip){save(equip(g,selected,b.dataset.equip));inform("已为"+HEROES.find(h=>h.id===selected).name+"装备"+GEAR[b.dataset.equip].name+"。原装备保留在个人库。");}
 else switch(b.dataset.guild){
 case 'check':switchPanel('departure');return;
 case 'backup':download('sunken-abbey-guild.json',g||{unreadable:raw});return;
 case 'prepare':loadConfig(guildConfig(g,getConfig()));inform('公会装备与永久训练已载入。修改指令后请使用“公会出征”；实验配置中的装备与训练不会覆盖公会资产。');return;
 case 'depart':save(depart(g,getConfig()));showReport(pendingReport(g));inform('公会远征已记录。请返回公会领取奖励；刷新后可恢复战报与待结算状态。');break;
 case 'report':showReport(pendingReport(g));break;
 case 'claim':{const hasLoot=(pendingReward(g).loot||[]).length>0;save(claim(g));selected=g.command?.heroId||selected;pane=hasLoot?'equipment':'team';}inform('奖励已存入公会，出战者已获得经验；候补保留原成长，装备和训练保留。');break;
 case 'retrain':save(retrain(g,selected));break;
 }render();}catch(e){inform(e.message);}};
 root.onchange=async e=>{if(e.target.id==='companion-room'){companionRoom=e.target.value;render();return;}if(e.target.dataset.companion){previews[e.target.dataset.companion]=e.target.value;inform('正在预览，点击应用此职责后才会用于出征。');render();return;}if(e.target.id==='history-compare-mode'){compareMode=e.target.value;render();root.querySelector('#history-comparison')?.scrollIntoView({block:'start'});return;}if(e.target.id==='equipment-slot'){equipmentSlot=e.target.value;render();return;}if(e.target.id==='gear-filter'){gearFilter=e.target.value;render();return;}if(e.target.id==='check-scope'){checkScope=e.target.value;render();return;}if(['loot-member','gear-member'].includes(e.target.id)){selected=e.target.value;render();return;}if(e.target.id!=='guild-import')return;try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('备份文件过大');const next=migrateGuild(JSON.parse(await file.text()));if(!confirm('恢复备份将替换当前公会。建议先导出当前备份。继续？'))return;save(next);render();inform('公会备份已恢复。');}catch(e){inform('无法恢复：'+e.message);}};
 function open(next='hero'){pane=typeof next==='string'?next:'hero';read();render();view('guild');window.scrollTo({top:0});}
 document.querySelector('header [data-view="guild"]').onclick=open;
 document.querySelector('#guild-run').onclick=()=>{open('departure');root.querySelector('.guild-tabs')?.scrollIntoView({block:'start'});};
 read();render();return {open,heroId:()=>g?.command?.heroId||null};
}
